<?php
declare(strict_types=1);namespace Kios\MerchantOperations;
final class SubscriptionView {
 private static function h(mixed $x):string{return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');}
 private static function label(string $f):string{return ['menu'=>'Menu management','inventory'=>'Inventory','recipes'=>'Recipes','floor'=>'Floor management','reservations'=>'Reservations','pos'=>'Staff POS','kitchen'=>'Kitchen operations','analytics'=>'Operational analytics','billing'=>'Bill preparation','branding'=>'Branding studio','multi_outlet'=>'Multi-outlet management','staff'=>'Staff management'][$f]??$f;}
 private static function ceilings(string $json):string{$d=json_decode($json,true);$parts=[];foreach(['outlets'=>'outlets','products'=>'products','staff'=>'staff accounts','tables'=>'tables']as$k=>$label)$parts[]=number_format((int)$d[$k]).' '.$label;return implode(' · ',$parts);}
 private static function modules(string $json):string{return implode(', ',array_map([self::class,'label'],json_decode($json,true)));}
 private static function table(array $headers,array $rows):string{$x='<div class="subscription-scroll" tabindex="0"><table><thead><tr>';foreach($headers as$h)$x.='<th>'.self::h($h).'</th>';$x.='</tr></thead><tbody>';foreach($rows as$r){$x.='<tr>';foreach($r as$v)$x.='<td>'.self::h($v).'</td>';$x.='</tr>';}return $x.'</tbody></table></div>';}
 private static function hidden(string $n,string $v):string{return '<input type="hidden" name="'.self::h($n).'" value="'.self::h($v).'">';}
 private static function input(string $label,string $name,string $value='',string $type='text'):string{return '<label>'.self::h($label).'<input name="'.self::h($name).'" type="'.$type.'" value="'.self::h($value).'" required></label>';}
 public static function render(array $d,string $csrf,bool $platform=false,string $selected='',bool $saved=false):string{
  $administrative=$d['administrative']??['merchant'=>'ACTIVE_DEMO','outlet'=>'ACTIVE_DEMO'];$administrativelyAllowed=$administrative['merchant']==='ACTIVE_DEMO'&&$administrative['outlet']==='ACTIVE_DEMO';
  $h=fn($v)=>self::h($v);$x='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Demonstration plans · KIOS</title><link rel="stylesheet" href="/assets/merchant-setup.css"><link rel="stylesheet" href="/assets/subscriptions.css"><script src="/assets/subscriptions.js" defer></script></head><body><main data-subscriptions'.(!$platform?' data-merchant="'.$h($d['merchant']).'" data-outlet="'.$h($d['outlet']).'"':'').'><header><div><p class="eyebrow">Private SaaS foundation</p><h1>'.($platform?'Platform Plan Manager':'Subscription overview').'</h1><p>Demonstration entitlements only. No subscription charges, invoices or commercial activation.</p></div></header>';
  if($platform&&PlatformAccess::enabled())$x.='<a href="/merchant.php?platform=overview">Back to platform administration</a>';
  if($saved)$x.='<p role="status">Versioned demonstration configuration saved.</p>';
  $x.='<nav aria-label="Subscription sections"><a href="#status">'.($platform?'Configure plans':'Entitlement status').'</a><a href="#comparison">Feature comparison</a><a href="#history">Assignment history</a><a href="#lifecycle-history">Lifecycle history</a></nav>';
  if($platform && ($d['lifecycle']??null))$x.=SubscriptionLifecycleView::platform($d['lifecycle'],$d['plans'],$csrf);
  if($platform){$plan=null;foreach($d['plans']as$p)if($p['plan_id']===$selected)$plan=$p;$features=$plan?json_decode($plan['features_json'],true):[];$limits=$plan?json_decode($plan['limits_json'],true):array_map(fn()=>0,Entitlements::LIMITS);
   $x.='<section class="panel" id="status"><h2>Create or revise a plan</h2><p>Each save creates an immutable version. Existing assignments retain their exact approved plan version; retirement blocks new assignments only.</p><div class="subscription-plan-links"><a href="?plans=1">New plan</a>';foreach($d['plans']as$p)$x.='<a href="?plans=1&amp;plan_id='.$h($p['plan_id']).'">'.$h($p['name']).' · v'.$p['version'].'</a>';$x.='</div><form method="post" data-subscription-form>'.self::hidden('_csrf',$csrf).self::hidden('action','plans-save').self::hidden('request',bin2hex(random_bytes(16))).self::hidden('version',(string)($plan['version']??0)).self::input('Stable plan identifier','plan_id',$plan['plan_id']??'').self::input('Plan name','name',$plan['name']??'').self::input('Description','description',$plan['description']??'').'<fieldset><legend>Enabled modules</legend><div class="subscription-features">';foreach(Entitlements::FEATURES as$f)$x.='<label><input type="checkbox" name="features[]" value="'.$f.'"'.(in_array($f,$features,true)?' checked':'').'>'.$h(self::label($f)).'</label>';$x.='</div></fieldset><fieldset><legend>Creation ceilings · existing records are never deleted</legend><div class="subscription-grid">';foreach(Entitlements::LIMITS as$k=>$max)$x.=self::input(ucfirst($k).' limit (0–'.$max.')','limits['.$k.']',(string)$limits[$k],'number');$x.='</div></fieldset><label>Plan availability<select name="active"><option value="1">Active for new assignments</option><option value="0"'.($plan&&!(int)$plan['active']?' selected':'').'>Inactive for new assignments</option></select></label><label>Optional illustrative metadata · INR paise, never charged<input name="metadata" value="'.$h($plan['metadata_paise']??'').'" inputmode="numeric"></label><button>Save plan version</button></form></section><section class="panel"><h2>Assign a demonstration plan</h2><p>Use the merchant’s current revision below. Scheduled versions take effect in UTC; expiry denies new use. Finish active services, occupancy and bookings before removing operational modules.</p><form method="post" data-subscription-form>'.self::hidden('_csrf',$csrf).self::hidden('action','plans-assign').self::hidden('request',bin2hex(random_bytes(16))).'<label>Merchant<select name="merchant">';foreach($d['merchants']as$m)$x.='<option value="'.$h($m['merchant_id']).'">'.$h($m['name']).' · assignment revision '.$m['version'].'</option>';$x.='</select></label>'.self::input('Expected assignment revision','expected','0','number').'<label>Latest active plan<select name="choice">';foreach($d['plans']as$p)if((int)$p['active'])$x.='<option value="'.$h($p['plan_id']).':'.$p['version'].'">'.$h($p['name']).' · v'.$p['version'].'</option>';$x.='</select></label>'.self::input('Effective · UTC','effective',gmdate('Y-m-d\TH:i'),'datetime-local').self::input('Expires · UTC','expires',gmdate('Y-m-d\TH:i',time()+365*86400),'datetime-local').self::input('Assignment reason','reason').'<button>Save merchant assignment</button></form></section>';
  }else{$a=$d['assignment'];$x.='<section class="panel" id="status"><h2>'.$h($d['state']).'</h2><p>'.($a?$h($a['name']).' · plan version '.$a['plan_version'].' · assignment revision '.$a['version']:'No effective assignment. Ask an authorized platform administrator.').'</p>';if(!$administrativelyAllowed)$x.='<p class="subscription-admin-notice" role="status"><strong>Administrative access restricted</strong> · Merchant: '.$h($administrative['merchant']).' · Outlet: '.$h($administrative['outlet']).'. New licensed work is unavailable; authorized completion and account setup remain separate.</p>';if($d['lifecycle']??null)$x.=SubscriptionLifecycleView::status($d['lifecycle']);if($a)$x.='<p>Effective '.gmdate('Y-m-d H:i',(int)$a['effective_epoch']).' UTC → expires '.gmdate('Y-m-d H:i',(int)$a['expires_epoch']).' UTC</p>';$x.='<p>Entitlements add restrictions; they never grant staff roles. Expired access blocks new work. Existing operational completion paths remain subject to staff permissions and current-resource state checks.</p><div class="subscription-features">';foreach(Entitlements::FEATURES as$f){$yes=$administrativelyAllowed&&$a&&in_array($d['state'],['TRIAL','ACTIVE','GRACE'],true)&&in_array($f,json_decode($a['features_json'],true),true);$x.='<article><strong>'.$h(self::label($f)).'</strong><span>'.($yes?'Included · staff permission also required':($administrativelyAllowed?'Restricted · no current entitlement':'Restricted · administrative access')).'</span></article>';}$x.='</div></section>';}
  $rows=[];foreach($d['plans']as$p)$rows[]=[$p['name'],$p['plan_id'],self::modules($p['features_json']),self::ceilings($p['limits_json'])];$x.='<section class="panel" id="comparison"><h2>Configured demonstration plans</h2><p>Starter, Growth and Enterprise are illustrative names, not commercial products.</p>'.self::table(['Plan','Identifier','Modules','Creation ceilings'],$rows).'</section>';$rows=[];foreach($d['history']as$a)$rows[]=[($platform?(array_column($d['merchants'],'name','merchant_id')[$a['merchant_id']]??$a['merchant_id']):'This merchant'),$a['version'],$a['plan_id'].' v'.$a['plan_version'],gmdate('Y-m-d H:i',(int)$a['effective_epoch']).' UTC',gmdate('Y-m-d H:i',(int)$a['expires_epoch']).' UTC',$a['reason']];$x.='<section class="panel" id="history"><h2>Immutable assignment history</h2>'.self::table(['Merchant','Revision','Plan','Effective','Expires','Reason'],$rows).'</section>';if($platform){$rows=[];foreach($d['versions']as$v)$rows[]=[$v['plan_id'],$v['version'],$v['name'],$v['description'],$v['active']?'Assignable at that version':'Inactive at that version',self::modules($v['features_json']),self::ceilings($v['limits_json']),$v['actor_id'],gmdate('Y-m-d H:i',(int)$v['created_epoch']).' UTC'];$x.='<section class="panel"><h2>Immutable plan-version audit</h2>'.self::table(['Plan','Version','Name','Description','Availability','Features','Limits','Actor','Recorded'],$rows).'</section>';}if(!$platform&&($d['lifecycleHistory']??[]))$x.=SubscriptionLifecycleView::history($d['lifecycleHistory']);return $x.'</main></body></html>';
 }
}
